buggyCode:
record OrderUpdate(long id, String shippingAddress) {}

@Component("orderAuthz")
class OrderAuthz {
    public boolean isOwner(long orderId, Authentication auth) {
        return orders.findById(orderId)
                .map(o -> o.owner().equals(auth.getName()))
                .orElse(false);
    }
}

@RestController
@RequestMapping("/orders")
class OrderController {

    @GetMapping("/{id}")
    @PreAuthorize("@orderAuthz.isOwner(#id, authentication)")
    Order get(@PathVariable long id) { return orders.findById(id).orElseThrow(); }

    @PutMapping("/{id}")
    @PreAuthorize("@orderAuthz.isOwner(#id, authentication)")
    Order update(@PathVariable long id, @RequestBody OrderUpdate body) {
        Order current = orders.findById(body.id()).orElseThrow();
        return orders.save(new Order(current.id(), current.owner(), body.shippingAddress()));
    }
}

