record AddressChange(String shippingAddress) {} // không có id: chỉ một nguồn sự thật là URL

@PutMapping("/{id}/address")
ResponseEntity<Void> changeAddress(@PathVariable long id,
                                   @RequestBody AddressChange body,
                                   Authentication auth) {
    // UPDATE orders SET shipping_address = ? WHERE id = ? AND owner = ?
    int updated = orders.updateAddress(id, auth.getName(), body.shippingAddress());
    if (updated == 0) {
        throw new ResponseStatusException(HttpStatus.NOT_FOUND); // không lộ đơn có tồn tại
    }
    return ResponseEntity.noContent().build();
}

